// ── Google Form emails ──────────────────────────────────────────
const rows = [];

function matchLine(text, label) {
  const pattern = new RegExp(`${label}\\s*[:\\-]\\s*(.+)`, 'i');
  const found = text.match(pattern);
  return found ? found[1].split('\n')[0].trim() : '';
}

for (const item of items) {
  const src = item.json;
  const text = [src.textPlain, src.snippet, src.textHtml]
    .filter(Boolean)
    .join('\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ');

  rows.push({
    json: {
      source:            'google_form',
      client_site:       'google_form',
      external_id:       src.id || src.messageId,
      full_name:         matchLine(text, 'Name') || src.from?.value?.[0]?.name || '',
      email:             matchLine(text, 'Email') || src.from?.value?.[0]?.address || '',
      phone:             matchLine(text, 'Phone|Mobile'),
      address:           matchLine(text, 'Address'),
      suburb:            matchLine(text, 'Suburb|Location|Area'),
      service_requested: matchLine(text, 'Service|Service Requested|Job Description'),
      message:           matchLine(text, 'Message|Comments|Details|Additional Information|Project Summary'),
      page_url:          matchLine(text, 'Page URL'),
      raw_payload:       src,
      received_at:       src.date || new Date().toISOString()
    }
  });
}

return rows;

