// ── Same Day Home Services (HTML email) ─────────────────────────
// Fields are in a styled HTML table, NOT plain key: value lines.
// Strategy: strip HTML tags to get plain text, then match table cell pairs.
const rows = [];

function matchLine(text, label) {
  const pattern = new RegExp(`${label}\\s*[:\\-]?\\s*([^\\n]+)`, 'i');
  const found = text.match(pattern);
  return found ? found[1].trim() : '';
}

for (const item of items) {
  const src = item.json;

  // Strip HTML and normalise whitespace for table-based emails
  const rawHtml = src.textHtml || '';
  const stripped = rawHtml
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/tr>/gi, '\n')
    .replace(/<\/td>/gi, ' | ')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const text = [src.textPlain, src.snippet, stripped]
    .filter(Boolean)
    .join('\n');

  rows.push({
    json: {
      source:            'same_day_home_services',
      client_site:       'samedayhomeservices.com.au',
      external_id:       src.id || src.messageId,
      full_name:         matchLine(text, 'Customer Name'),
      email:             matchLine(text, 'Email'),
      phone:             matchLine(text, 'Phone'),
      address:           '',
      suburb:            '',
      service_requested: matchLine(text, 'Requested Service'),
      message:           matchLine(text, 'Project Summary|Additional Information|Message|Comments|Details'),
      page_url:          '',
      raw_payload:       src,
      received_at:       src.date || new Date().toISOString()
    }
  });
}

return rows;

